argv:
$ErrorActionPreference='Stop'
try{
 $data=& gh.exe api --method GET 'repos/foto6/WebAIBridge/check-suites/104386851325/check-runs' 2>$null |ConvertFrom-Json
 if($LASTEXITCODE -ne 0){throw 'GH_API_FAIL'}
 foreach($r in @($data.check_runs)){
  Write-Output ('CHECK_NAME='+[string]$r.name)
  Write-Output ('CHECK_STATUS='+[string]$r.status)
  Write-Output ('CHECK_CONCLUSION='+[string]$r.conclusion)
  $message=[string]$r.output.summary
  Write-Output ('CHECK_SUMMARY='+$message.Replace([Environment]::NewLine,' ').Substring(0,[Math]::Min(500,$message.Length)))
  Write-Output ('CHECK_ANNOTATIONS_COUNT='+[string]$r.output.annotations_count)
 }
}catch{Write-Output ('CHECK_RUN_DETAILS_UNAVAILABLE='+[string]$_.Exception.GetType().Name)}
Write-Output 'READ_ONLY=True'
